package com.commercecore.order;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;@Entity@Table(name="order_status_history")public class OrderStatusHistory{@Id@GeneratedValue(strategy=GenerationType.UUID)private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="order_id",nullable=false)private CustomerOrder order;@Enumerated(EnumType.STRING)@Column(name="from_status",length=20)private OrderStatus fromStatus;@Enumerated(EnumType.STRING)@Column(name="to_status",nullable=false,length=20)private OrderStatus toStatus;@Column(name="actor_user_id")private UUID actorUserId;@Column(length=500)private String reason;@Column(name="reference_key",length=160)private String reference;@Column(name="occurred_at",nullable=false,updatable=false)private Instant occurredAt;protected OrderStatusHistory(){}public OrderStatusHistory(CustomerOrder o,OrderStatus from,OrderStatus to,UUID actor,String reason,String reference,Instant at){order=o;fromStatus=from;toStatus=to;actorUserId=actor;this.reason=reason;this.reference=reference;occurredAt=at;}public UUID getId(){return id;}public OrderStatus getFromStatus(){return fromStatus;}public OrderStatus getToStatus(){return toStatus;}public UUID getActorUserId(){return actorUserId;}public String getReason(){return reason;}public String getReference(){return reference;}public Instant getOccurredAt(){return occurredAt;}}
